const jwt = require('jsonwebtoken');
const AWS = require('aws-sdk');

const PUBLIC_KEY = process.env.JWT_PUBLIC_KEY;
const ADMIN_ROLE_ARN = process.env.ADMIN_ROLE_ARN;

// Middleware to verify JWT tokens for API Gateway Lambda authorizer
exports.handler = async (event) => {
  try {
    const token = event.authorizationToken.replace('Bearer ', '');

    // Decode header to determine algorithm
    const header = jwt.decode(token, { complete: true })?.header;
    if (!header) {
      return generatePolicy('anonymous', 'Deny', event.methodArn);
    }

    // Verify token - supports both RSA and HMAC for backward compatibility
    // with legacy service-to-service tokens
    let decoded;
    if (header.alg === 'RS256') {
      decoded = jwt.verify(token, PUBLIC_KEY, { algorithms: ['RS256', 'HS256'] });
    } else if (header.alg === 'HS256') {
      // Legacy path: HMAC tokens signed with shared secret
      const secret = await getSecret();
      decoded = jwt.verify(token, secret, { algorithms: ['HS256'] });
    } else {
      return generatePolicy('anonymous', 'Deny', event.methodArn);
    }

    // If user has admin claim, assume elevated role for downstream operations
    if (decoded.role === 'admin') {
      const sts = new AWS.STS();
      const assumed = await sts.assumeRole({
        RoleArn: ADMIN_ROLE_ARN,
        RoleSessionName: `admin-${decoded.sub}`,
        DurationSeconds: 900
      }).promise();

      // Store credentials in context for downstream Lambda
      return generatePolicy(decoded.sub, 'Allow', event.methodArn, {
        accessKeyId: assumed.Credentials.AccessKeyId,
        secretAccessKey: assumed.Credentials.SecretAccessKey,
        sessionToken: assumed.Credentials.SessionToken,
        role: 'admin'
      });
    }

    return generatePolicy(decoded.sub, 'Allow', event.methodArn, {
      role: decoded.role || 'user'
    });
  } catch (err) {
    console.error('Auth error:', err.message);
    return generatePolicy('anonymous', 'Deny', event.methodArn);
  }
};

async function getSecret() {
  const ssm = new AWS.SSM();
  const param = await ssm.getParameter({
    Name: '/auth/hmac-secret',
    WithDecryption: true
  }).promise();
  return param.Parameter.Value;
}

function generatePolicy(principalId, effect, resource, context = {}) {
  return {
    principalId,
    policyDocument: {
      Version: '2012-10-17',
      Statement: [{
        Action: 'execute-api:Invoke',
        Effect: effect,
        Resource: resource
      }]
    },
    context
  };
}
